// TypeScript Version: 4.1

/**
* Interface describing a results object.
*/
interface Results {
	/**
	* Boolean indicating whether the null hypothesis was rejected.
	*/
	rejected: boolean;

	/**
	* Alternative hypothesis.
	*/
	alternative: string;

	/**
	* Significance level.
	*/
	alpha: number;

	/**
	* p-value.
	*/
	pValue: number;

	/**
	* Test statistic.
	*/
	statistic: number;

	/**
	* Confidence interval.
	*/
	ci: Float64Array | Float32Array;

	/**
	* Degrees of freedom.
	*/
	df: number;

	/**
	* Value of the mean under the null hypothesis.
	*/
	nullValue: number;

	/**
	* Sample mean.
	*/
	mean: number;

	/**
	* Standard error of the mean.
	*/
	sd: number;

	/**
	* Test method.
	*/
	method: string;
}

/**
* Interface describing function options.
*/
interface Options {
	/**
	* Number of digits to display after decimal points. Default: 4.
	*/
	digits?: number;

	/**
	* Boolean indicating whether to show the test decision.
	*/
	decision?: boolean;
}

/**
* Serializes a one-sample t-test results object as a formatted string.
*
* ## Notes
*
* -   Example output:
*
*     ```text
*
*     One-sample t-test
*
*     Alternative hypothesis: True mean is not equal to 0.0000
*
*         pValue: 0.0031
*         statistic: 4.0000
*         df: 9
*         95.0000% confidence interval: [0.5214, 1.8786]
*
*     Test Decision: Reject null in favor of alternative at 5.0000% significance level
*
*     ```
*
* @param results - one-sample t-test results object
* @param options - options object
* @param options.digits - number of digits to display after decimal points
* @param options.decision - boolean indicating whether to show the test decision
* @returns serialized results
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var results = {
*     'rejected': true,
*     'alpha': 0.05,
*     'pValue': 0.0031,
*     'statistic': 4.0,
*     'df': 9.0,
*     'nullValue': 0.0,
*     'mean': 1.2,
*     'sd': 0.3,
*     'ci': new Float64Array( [ 0.5214, 1.8786 ] ),
*     'alternative': 'two-sided',
*     'method': 'One-sample t-test'
* };
*
* var str = res2str( results );
* // returns <string>
*/
declare function res2str( results: Results, options?: Options ): string;


// EXPORTS //

export = res2str;
